 content+=`<div class="detail-section"><h4>${r.resource?'会话 / 资源标识':'执行对象'}</h4><div class="target-box"><code>${esc(r.resource?r.id:r.target)}</code>${copy(r.resource?r.id:r.target,'复制执行对象')}</div></div>`;
