function completeDemo(){if(scene==='empty'){notify('请切换到执行示例');return}const r=live.find(r=>r.id===selected)||live.find(r=>r.status==='running');if(!r){notify('当前示例调用已全部归档');return}if(r.status==='queued'){r.status='running';r.start=now();render();notify('演示：排队任务已开始执行');return}const completed={...r,status:'success',end:now(),duration:now()-r.start};if(completed.async){completed.target=completed.job+' · 8 / 8 步';const resource=resources.find(x=>x.session===completed.session);if(resource){resource.target='Web · 已连接';resource.meta['任务状态']='已完成'}}live=live.filter(x=>x.id!==r.id);history.unshift(completed);render();notify(`演示：${r.tool} 已完成，可在历史记录中查看`);}
