document.querySelector('.view-tabs').addEventListener('keydown',e=>{const views=['live','history','resources'];const next=e.key==='ArrowRight'?views[(views.indexOf(view)+1)%3]:e.key==='ArrowLeft'?views[(views.indexOf(view)+2)%3]:e.key==='Home'?'live':e.key==='End'?'resources':null;if(next){e.preventDefault();changeView(next);$('tab-'+next).focus()}});
setInterval(()=>{if(scene==='sample'){ticks++;document.querySelectorAll('[data-elapsed],[data-detail-elapsed]').forEach(el=>{const r=[...live,...resources].find(x=>x.id===(el.dataset.elapsed||el.dataset.detailElapsed));if(r)el.textContent=duration(now()-r.start)})}},1000);
